import ctypes
import importlib.util
import logging
import os
import platform
from pathlib import Path

_LOGGER = logging.getLogger(__name__)


_RUNTIME_DIR = Path(__file__).resolve().parent

if importlib.util.find_spec("usd_convert_cad") is not None:
    from usd_convert_cad import configure_runtime_paths

    configure_runtime_paths()


def _preload_linux_runtime_libraries() -> None:
    if os.name != "posix":
        return

    mode = getattr(os, "RTLD_NOW", 0) | getattr(os, "RTLD_GLOBAL", 0)
    lazy_mode = getattr(os, "RTLD_LAZY", 0) | getattr(os, "RTLD_GLOBAL", 0)
    is_linux_x86_64 = platform.system() == "Linux" and platform.machine().lower() in {"x86_64", "amd64"}
    linux_dependency_libraries = (
        "libtbb.so.12",
        "libMaterialXCore.so*",
        "libMaterialXFormat.so*",
    )
    required_libraries = (
        "libusd_tf.so",
        "libusd_arch.so",
        "libusd_vt.so",
        "libusd_work.so",
        "libusd_gf.so",
        "libusd_sdf.so",
        "libusd_ar.so",
        "libusd_kind.so",
        "libusd_python.so",
        "libusd_usd.so",
        "libusd_usdGeom.so",
        "libusd_usdLux.so",
        "libusd_usdPhysics.so",
        "libusd_usdShade.so",
        "libusd_usdUI.so",
        "libusd_usdUtils.so",
        "libusdex_core.so",
        "libusdex_rtx.so",
    )
    optional_libraries = ("libomni_transcoding.so",)
    hoops_exchange_libraries = ("TB_Loader.tx", "libA3DLIBS.so") if is_linux_x86_64 else ("libA3DLIBS.so",)
    converter_libraries = ("libomni_converter_hoops.so",)

    for library_pattern in linux_dependency_libraries:
        library_paths = sorted(_RUNTIME_DIR.glob(library_pattern))
        if library_paths:
            ctypes.CDLL(str(library_paths[-1]), mode=mode)

    for library_name in optional_libraries:
        library_path = _RUNTIME_DIR / library_name
        if library_path.is_file():
            ctypes.CDLL(str(library_path), mode=mode)

    for library_name in required_libraries:
        library_path = _RUNTIME_DIR / library_name
        if library_path.is_file():
            ctypes.CDLL(str(library_path), mode=mode)
        else:
            _LOGGER.warning("Skipping missing runtime library: %s", library_path)

    for library_name in hoops_exchange_libraries:
        library_path = _RUNTIME_DIR / library_name
        if library_path.is_file():
            ctypes.CDLL(str(library_path), mode=lazy_mode)
        else:
            _LOGGER.warning("Skipping missing runtime library: %s", library_path)

    for library_name in converter_libraries:
        library_path = _RUNTIME_DIR / library_name
        if library_path.is_file():
            ctypes.CDLL(str(library_path), mode=mode)
        else:
            _LOGGER.warning("Skipping missing runtime library: %s", library_path)


_preload_linux_runtime_libraries()

# Force-load pxr Python bindings used by the native module's pybind11 converters
# (SdfLayer::FileFormatArguments, TfToken, etc.) before importing the extension,
# so its init cannot abort when callers have not pre-imported pxr.
from pxr import Sdf, Tf  # noqa: F401

